import { type Compiler, FileSystem, type Package, path, JSON5 } from '@servicenow/sdk-build-core'

export function createPackageJson({
    rootDir,
    compiler,
    fileSystem,
}: {
    rootDir: string
    compiler: Compiler
    fileSystem: FileSystem
}): Package {
    const packageJsonFilePath = path.join(rootDir, 'package.json')
    const packageJsonFile = compiler.getSourceFile(packageJsonFilePath)
    if (!packageJsonFile && !FileSystem.existsSync(fileSystem, packageJsonFilePath)) {
        return { name: 'my-fluent-app', version: '0.0.1' }
    }

    const packageJsonText = packageJsonFile
        ? packageJsonFile.getFullText()
        : fileSystem.readFileSync(packageJsonFilePath, { encoding: 'utf-8' })

    return JSON5.parse(packageJsonText)
}

export function getPackageJsonFilePath(rootDir: string): string {
    return path.join(rootDir, 'package.json')
}

/**
 * Validates the package name according to the npm package naming conventions.
 */
export function validatePackageName(name: string): void {
    if (name === null) {
        throw new Error('name cannot be null')
    }

    if (name === undefined) {
        throw new Error('name cannot be undefined')
    }

    if (!name.length) {
        throw new Error('name length must be greater than zero')
    }

    if (name.match(/^\./)) {
        throw new Error('name cannot start with a period')
    }

    if (name.match(/^_/)) {
        throw new Error('name cannot start with an underscore')
    }

    if (name.trim() !== name) {
        throw new Error('name cannot contain leading or trailing spaces')
    }

    if (encodeURIComponent(name) !== name) {
        const scopedPackagePattern = /^(?:@([^/]+?)[/])?([^/]+?)$/

        // Maybe it's a scoped package name, like @user/package
        const nameMatch = name.match(scopedPackagePattern)
        if (nameMatch) {
            const user = nameMatch[1] as string
            const pkg = nameMatch[2] as string
            if (encodeURIComponent(user) === user && encodeURIComponent(pkg) === pkg) {
                return
            }
        }

        throw new Error('name can only contain URL-friendly characters')
    }
}
